create table if not exists categories(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,created_at timestamptz default now());
create table if not exists products(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),category_id uuid references categories(id),sku text not null,name text not null,unit text not null default 'PCS',mrp numeric(14,2) not null default 0,cost_price numeric(14,2) not null default 0,selling_price numeric(14,2) not null default 0,gst_rate numeric(5,2) not null default 0,pack_size numeric(14,3) not null default 1,active boolean not null default true,created_at timestamptz default now(),unique(tenant_id,sku));
create table if not exists customers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),code text,name text not null,customer_type text not null default 'retailer',phone text,address text,territory text,credit_limit numeric(14,2) default 0,active boolean default true,created_at timestamptz default now());
create table if not exists warehouses(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,location text,active boolean default true,created_at timestamptz default now());
create table if not exists inventory_ledger(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),warehouse_id uuid not null references warehouses(id),product_id uuid not null references products(id),quantity numeric(18,3) not null,unit_cost numeric(14,2) not null default 0,transaction_type text not null,reference_type text,reference_id uuid,idempotency_key text,created_at timestamptz default now(),unique(tenant_id,idempotency_key));
create table if not exists orders(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),customer_id uuid references customers(id),status text not null default 'draft',order_date timestamptz default now(),subtotal numeric(14,2) default 0,tax numeric(14,2) default 0,total numeric(14,2) default 0,created_at timestamptz default now());
create table if not exists order_lines(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id) on delete cascade,product_id uuid not null references products(id),quantity numeric(18,3) not null,unit_price numeric(14,2) not null,tax_rate numeric(5,2) default 0);
create table if not exists dispatches(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),order_id uuid references orders(id),warehouse_id uuid references warehouses(id),status text not null default 'pending',dispatched_at timestamptz,created_at timestamptz default now());
